name: mbridge-deps-sync

on:
  schedule:
    - cron: "0 0 * * *"
  workflow_dispatch:

permissions:
  contents: write
  pull-requests: write

jobs:
  sync-deps:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v6

      - name: Setup Python
        uses: actions/setup-python@v6
        with:
          python-version: "3.10"

      - name: Install dependencies
        run: |
          python -m pip install --upgrade pip
          pip install requests

      - name: Sync dependencies
        run: |
          python scripts/sync_mbridge_deps.py
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Create Pull Request
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const hasChanges = fs.existsSync('.github/dependabot.yml') && fs.readFileSync('.github/dependabot.yml', 'utf8').length > 0;

            if (hasChanges) {
              const { execSync } = require('child_process');

              execSync('git config user.name "github-actions[bot]"');
              execSync('git config user.email "github-actions[bot]@users.noreply.github.com"');
              execSync('git checkout -b chore/mbridge-deps-sync');
              execSync('git add .');

              try {
                execSync('git diff --staged --quiet');
                console.log('No changes to commit');
                return;
              } catch (e) {
                // Changes exist
              }

              execSync('git commit -m "chore: sync mbridge dependencies"');
              execSync('git push origin chore/mbridge-deps-sync --force');

              const { data: pr } = await github.rest.pulls.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                title: 'chore: sync mbridge dependencies',
                head: 'chore/mbridge-deps-sync',
                base: 'main',
                body: 'Automated dependency synchronization from mbridge.'
              });

              console.log(`Created PR #${pr.number}`);
            } else {
              console.log('No dependency changes detected');
            }
